-- Two related tables linked by a foreign key
CREATE TABLE customers (
  id SERIAL PRIMARY KEY,
  email TEXT UNIQUE NOT NULL
);

CREATE TABLE orders (
  id SERIAL PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(id),
  total_cents INTEGER NOT NULL,
  placed_at TIMESTAMPTZ DEFAULT now()
);

-- Reassemble the relationship at query time
SELECT c.email, o.total_cents
FROM orders o
JOIN customers c ON c.id = o.customer_id;

CREATE TABLE users (
  id SERIAL PRIMARY KEY,          -- identity, indexed automatically
  email TEXT UNIQUE NOT NULL,     -- no duplicates, indexed automatically
  team_id INTEGER REFERENCES teams(id) ON DELETE SET NULL -- must exist in teams
);

-- A non-unique performance index: correctness unchanged, reads faster
CREATE INDEX idx_users_team ON users(team_id);

-- 3NF: each fact lives once
CREATE TABLE customers (id SERIAL PRIMARY KEY, email TEXT UNIQUE);
CREATE TABLE products  (id SERIAL PRIMARY KEY, name TEXT, price_cents INT);
CREATE TABLE orders (
  id SERIAL PRIMARY KEY,
  customer_id INT REFERENCES customers(id),
  product_id INT REFERENCES products(id),
  qty INT NOT NULL
);

